package com.intermarche.e2e.engine.fieldops;
import com.intermarche.backoffice.domain.fieldops.*;
import com.intermarche.backoffice.domain.executing.*;
import com.intermarche.backoffice.domain.stock.*;
import com.intermarche.backoffice.domain.store.*;
import com.intermarche.backoffice.domain.util.DateTimeProvider;
import io.quarkus.test.junit.QuarkusTest;
import io.quarkus.narayana.jta.QuarkusTransaction;
import org.junit.jupiter.api.Test;
import java.util.*;
import java.math.BigDecimal;
import static org.junit.jupiter.api.Assertions.*;
@QuarkusTest @jakarta.enterprise.inject.Typed(DepositObservationTest.class)
class DepositObservationTest extends SupportTraceabilityTest {
 record Slot(long id,String scan,String carton){}
 Slot carton(){String code="BOX-"+f.store();long carton=support("CARTON",code),cart=support("CART","CART-"+f.store());var layout=call(f.manager(),"GET","/supports/"+cart+"/layout?storeId="+f.store(),null).then().statusCode(200).extract();layout=call(f.manager(),"PUT","/supports/layout",Map.of("storeId",f.store(),"cartId",cart,"rows",1,"columns",2,"expectedRevision",layout.<String>path("revision"))).then().statusCode(200).extract();long slot=layout.jsonPath().getLong("compartments[0].id");call(f.picker(),"POST","/supports/compartments",Map.of("storeId",f.store(),"compartmentId",slot,"supportId",carton,"orderId",f.order(),"expectedRevision",layout.<String>path("compartments[0].revision"),"requestKey",key())).then().statusCode(200);attach(code);return new Slot(slot,"COMPARTMENT:"+slot,code);}
 @Test void cartonAndCompartmentScansConfirmTheSamePhysicalDestination(){line();Slot slot=carton();call(f.picker(),"GET","/orders/"+f.order()+"/deposit-target?storeId="+f.store()+"&code="+slot.scan,null).then().statusCode(200).body("toteCode",org.hamcrest.Matchers.is(slot.carton));var c=command("PICK");c.putAll(Map.of("itemId",f.item(),"quantity",2,"toteCode",slot.carton,"depositScanCode",slot.scan));command(c).then().statusCode(200);command(c).then().statusCode(200);QuarkusTransaction.requiringNew().run(()->{var i=PickedItem.<PickedItem>findById(f.item());assertEquals(slot.carton,i.loadedTote.tote.code);assertEquals(1,PickedStockAllocation.count("state.itemId=?1 and quantity>0",f.item()));});}
 @Test void aMismatchedDestinationOrAnotherStoreCannotConfirmADeposit(){line();Slot slot=carton();attach(f.tote());var c=command("PICK");c.putAll(Map.of("itemId",f.item(),"quantity",1,"toteCode",f.tote(),"depositScanCode",slot.scan));command(c).then().statusCode(409);call(f.picker(),"GET","/orders/"+f.order()+"/deposit-target?storeId="+f.other()+"&code="+slot.scan,null).then().statusCode(403);call(f.picker(),"GET","/orders/"+f.order()+"/deposit-target?storeId="+f.store()+"&code=COMPARTMENT:0",null).then().statusCode(409);QuarkusTransaction.requiringNew().run(()->assertEquals(0,PickedStockAllocation.count("state.store.id=?1 and quantity>0",f.store())));}
 Map<String,Object> observation(String kind){var v=new LinkedHashMap<String,Object>();v.putAll(Map.of("storeId",f.store(),"orderId",f.order(),"productId",f.product(),"locationId",f.location(),"kind",kind,"title",kind.equals("EMPTY_LOCATION")?"Emplacement vide":"Écart de stock","comment","Constat terrain sans correction de stock","announcedQuantity",5,"observedQuantity",kind.equals("EMPTY_LOCATION")?0:2,"requestKey",key()));return v;}
 @Test void emptyLocationIsDistinctFromAMissingProductAndDoesNotChangeStock(){line();var packet=observation("EMPTY_LOCATION");long id=call(f.picker(),"POST","/incidents",packet).then().statusCode(200).extract().jsonPath().getLong("id");call(f.picker(),"POST","/incidents",packet).then().statusCode(200).body("id",org.hamcrest.Matchers.is((int)id));QuarkusTransaction.requiringNew().run(()->{var i=FieldIncident.<FieldIncident>findById(id);assertEquals("EMPTY_LOCATION",i.kind);assertEquals(0,i.observedQuantity.signum());assertEquals(f.location(),com.intermarche.backoffice.domain.fieldops.FieldEntityIds.id(i.location));assertEquals(0,PickingShortage.count("handlingOrder.id",f.order()));assertEquals(0,StockMovement.count("account.store.id",f.store()));});}
 @Test void stockDiscrepancyKeepsAnnouncedAndObservedQuantitiesWithoutAdjustment(){line();QuarkusTransaction.requiringNew().run(()->{var a=stock.account(f.store(),f.product());stock.adjust(a.id,f.location(),key(),BigDecimal.valueOf(5),DateTimeProvider.now());});call(f.picker(),"GET","/products/"+f.product()+"/location-stock?storeId="+f.store()+"&locationId="+f.location(),null).then().statusCode(200).body("announcedQuantity",org.hamcrest.Matchers.comparesEqualTo(5f));var packet=observation("STOCK_DISCREPANCY");long id=call(f.picker(),"POST","/incidents",packet).then().statusCode(200).extract().jsonPath().getLong("id");call(f.picker(),"POST","/incidents",packet).then().statusCode(200);QuarkusTransaction.requiringNew().run(()->{var i=FieldIncident.<FieldIncident>findById(id);assertEquals(0,BigDecimal.valueOf(5).compareTo(i.announcedQuantity));assertEquals(0,BigDecimal.valueOf(2).compareTo(i.observedQuantity));assertEquals(1,StockMovement.count("account.store.id",f.store()));});packet.put("requestKey",key());packet.put("observedQuantity",5);call(f.picker(),"POST","/incidents",packet).then().statusCode(400);packet.put("observedQuantity","1.5");call(f.picker(),"POST","/incidents",packet).then().statusCode(400);QuarkusTransaction.requiringNew().run(()->com.intermarche.backoffice.domain.order.Product.<com.intermarche.backoffice.domain.order.Product>findById(f.product()).productType=com.intermarche.backoffice.domain.order.ProductType.WEIGHT);packet.put("requestKey",key());packet.put("announcedQuantity","1.234567");packet.put("observedQuantity","1.2");call(f.picker(),"POST","/incidents",packet).then().statusCode(200);}
 @Test void aFullSupportKeepsItsContentsAndTheReplacementReceivesTheNextPick(){line();QuarkusTransaction.requiringNew().run(()->{var item=PickedItem.<PickedItem>findById(f.item());item.quantity=BigDecimal.valueOf(4);item.lotLine.quantity=BigDecimal.valueOf(4);supportCatalog.registerAll(Store.findById(f.store()));});attach(f.tote());var first=command("PICK");first.putAll(Map.of("itemId",f.item(),"quantity",2,"toteCode",f.tote()));command(first).then().statusCode(200);var mission=call(f.picker(),"GET","/orders/"+f.order()+"/supports?storeId="+f.store(),null).then().statusCode(200).extract();var load=mission.jsonPath().<Map<String,Object>>getList("loads").stream().filter(v->f.tote().equals(v.get("code"))).findFirst().orElseThrow();call(f.picker(),"POST","/supports/full",Map.of("storeId",f.store(),"loadedToteId",load.get("id"),"expectedRevision",load.get("revision"),"expectedOrderRevision",orderRevision(),"replacementCode",f.second(),"requestKey",key(),"reason","Support plein")).then().statusCode(200);long pending=QuarkusTransaction.requiringNew().call(()->PickedItem.<PickedItem>find("status=?1 and lotLine.id=(select i.lotLine.id from PickedItem i where i.id=?2)",PickedItem.PickStatus.PENDING,f.item()).firstResult().id);var second=command("PICK");second.putAll(Map.of("itemId",pending,"quantity",2,"toteCode",f.second(),"depositScanCode",f.second()));command(second).then().statusCode(200);command(second).then().statusCode(200);QuarkusTransaction.requiringNew().run(()->{for(String code:List.of(f.tote(),f.second())){var t=LoadedTote.<LoadedTote>find("tote.code=?1 and status=?2",code,LoadedTote.Status.IN_USE).firstResult();assertEquals(0,BigDecimal.valueOf(2).compareTo(t.items.stream().filter(v->v.status==PickedItem.PickStatus.PICKED).map(v->v.quantity).reduce(BigDecimal.ZERO,BigDecimal::add)));}});}
}
